--region import
---@type GroceryUtils
local GroceryUtils = import('Game.Grocery.GroceryUtils')
--endregion import

--region define
--endregion define

--- from: Assets/BundleResources/Prefabs/Common/CommonBuyItemDialog.prefab
---@class CommonExchangeMaterialNode
---@field Env                           	CommonExchangeMaterialNode              
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field Empty                         	UnityEngine.RectTransform               
---@field GoodsIconList                 	SuperScrollView.LoopGridView            
---@field Content                       	UnityEngine.RectTransform               
---@field TextNumber                    	UnityEngine.RectTransform               
---@field TextTitle                     	UnityEngine.RectTransform               
---@field ImgIcon                       	UnityEngine.RectTransform               
---@field ImgBg                         	UnityEngine.RectTransform               
---@field Quantity                      	UnityEngine.RectTransform               
---@field ExchangeMaterial              	UnityEngine.RectTransform               
local CommonExchangeMaterialNode = Class("CommonExchangeMaterialNode")

--region lifecycle
function CommonExchangeMaterialNode:__init()
    self._selectedItems = {}
    self._prices        = nil
    self._buyNum        = nil
    self._currencyList  = nil
end

function CommonExchangeMaterialNode:__delete()
    self._selectedItems = nil
    self._prices        = nil
    self._buyNum        = nil
    self._currencyList  = nil
end

function CommonExchangeMaterialNode:Start()
    self:InitHandler()
end

function CommonExchangeMaterialNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function CommonExchangeMaterialNode:InitHandler()
    
end

---初始化货币列表
function CommonExchangeMaterialNode:InitCurrencyList()
    
    local backpackComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.BackpackComponent)
    
    local quality = self:GetCurrencyQuality()
    local currencyList = {}
    local totalData = backpackComponent:GetGoodsByTypeId(Constants.IDType.GoodsSameCard)
    for _, v in ipairs(totalData) do
        if v.vo.quality == checkInt(quality) and checkInt(v.num) > 0 then
            table.insert(currencyList, v)
        end
    end
    table.sort(currencyList, function(a, b)
        return checkInt(a.goodsId) < checkInt(b.goodsId)
    end)

    self._currencyList = currencyList
end

---初始化选中列表
function CommonExchangeMaterialNode:InitSelectedItems()
    local selectedItems = {}
    local targetNum = self:GetMaxSelectedNum()
    local curNum = 0
    for i, v in ipairs(self:GetCurrencyList()) do
        local itemNum = checkInt(v.num)
        local num = targetNum - curNum
        if num > itemNum then
            selectedItems[i] = itemNum
            curNum = curNum + itemNum
        else
            selectedItems[i] = num
            break
        end
    end
    
    self._selectedItems = selectedItems
end
--endregion init

--region handler
function CommonExchangeMaterialNode:OnGetItemByIndex(listView, index)
    if index < 0 then return end

    local idx = index + 1
    local cell = listView:NewListViewItem("Cell")
    local goodsNode = cell.transform:Find('GoodNode')
    local data = self:GetCurrencyList()[idx]
    CfUtils.RefeshGoodGo2(goodsNode,data.goodsId, data.num, nil, nil, function()
        self:CellOnClickHandler(idx)
    end)
    
    local scr = self:GetCellScr(cell)
    if not isNull(scr) then
        scr:RefreshCell(self._selectedItems[idx], idx, Bind(self, self.BtnReduceOnClickHandler))
    end
    return cell
end

---cell点击回调
function CommonExchangeMaterialNode:CellOnClickHandler(index)
    if checkInt(self._selectedItems[index]) >= checkInt(self:GetCurrencyList()[index].num) then return end
    
    local maxNum = self:GetMaxSelectedNum()
    local curNum = self:GetCurrentSelectedNum()
    if curNum >= maxNum then
        GameUtils.Toast(localize('已选择足够多的核心'))
        return 
    end
    
    self:SelectItem(index)
end

---减少按钮点击回调
function CommonExchangeMaterialNode:BtnReduceOnClickHandler(index)
    self:UnselectItem(index)
end
--endregion handler

--region public
---初始化节点
---@param prices table   价格 key为品质，value.current为价格
---@param buyNum integer 购买数量
function CommonExchangeMaterialNode:InitNode(prices, buyNum)
    self._prices = checkTable(prices)
    self._buyNum = checkInt(buyNum)
    
    CfUtils.SetUISwitchText(self.TextTitle, 2)
    
    self:InitCurrencyList()
    self:InitSelectedItems()
    
    self:RefreshList()
    self:RefreshCurrencyIcon()
    self:RefreshSelectedNum()
end

---设置购买数量
---@param buyNum integer 购买数量
function CommonExchangeMaterialNode:SetBuyNum(buyNum)
    self._buyNum = checkInt(buyNum)
    
    self:InitSelectedItems()
    
    self:RefreshList()
    self:RefreshSelectedNum()
end

---获取最大购买数量
function CommonExchangeMaterialNode:GetMaxBuyNum()
    local key = table.keys(self._prices)[1]
    local cost = checkInt(self._prices[key].current)
    local currencyNum = 0
    for i, v in ipairs(self:GetCurrencyList()) do
        currencyNum = currencyNum + checkInt(v.num)
    end
    return math.floor(currencyNum / cost)
end

---检查选中物品是否足够
function CommonExchangeMaterialNode:CheckItemEnough()
    local maxNum = self:GetMaxSelectedNum()
    local curNum = self:GetCurrentSelectedNum()
    return curNum == maxNum
end

---获取道具消耗
function CommonExchangeMaterialNode:GetItemsCost()
    local cost = {}
    local currencyList = self:GetCurrencyList()
    for k, v in pairs(self._selectedItems) do
        if v > 0 then
            local tmp = {goodsId = currencyList[k].goodsId, num = v}
            table.insert(cost, tmp)
        end
    end
    
    return cost
end

---清除全部选中的物品
function CommonExchangeMaterialNode:ClearSelectedItem()
    self._selectedItems = {}
    self:RefreshList()
    self:RefreshSelectedNum()
end
--endregion public

--region private
---刷新道具列表
function CommonExchangeMaterialNode:RefreshList()
    local currencyList = self:GetCurrencyList()
    local isEmpty = #currencyList == 0
    CfUtils.SetActive(self.Content, not isEmpty)
    CfUtils.SetActive(self.Empty, isEmpty)
    if isEmpty then return end
    
    if not self.GoodsIconList.IsListViewInit then
        self.GoodsIconList:InitGridView(#currencyList, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.GoodsIconList, #currencyList)
    end
end

---刷新货币icon
function CommonExchangeMaterialNode:RefreshCurrencyIcon()
    local path = GroceryUtils.GetCoinImageByQuality(self:GetCurrencyQuality())
    CfUtils.FillImage(self.ImgIcon, path)
end

---刷新选中数量
function CommonExchangeMaterialNode:RefreshSelectedNum()
    local maxNum = self:GetMaxSelectedNum()
    local curNum = self:GetCurrentSelectedNum()
    CfUtils.FillText(self.TextNumber, string.format('%d/%d', curNum, maxNum))
end

---选中物品
function CommonExchangeMaterialNode:SelectItem(index)
    if self._selectedItems[index] then
        self._selectedItems[index] = self._selectedItems[index] + 1
    else
        self._selectedItems[index] = 1
    end
    self:RefreshSelectedNum()
    local cell = self.GoodsIconList:GetShownItemByItemIndex(index - 1)
    local scr = self:GetCellScr(cell)
    if not isNull(scr) then
        scr:SetSelectedNum(self._selectedItems[index])
    end
end

---取消选中物品
function CommonExchangeMaterialNode:UnselectItem(index)
    if self._selectedItems[index] then
        self._selectedItems[index] = self._selectedItems[index] - 1
    end
    self:RefreshSelectedNum()
    local cell = self.GoodsIconList:GetShownItemByItemIndex(index - 1)
    local scr = self:GetCellScr(cell)
    if not isNull(scr) then
        scr:SetSelectedNum(self._selectedItems[index])
    end
end

---获取货币质量
function CommonExchangeMaterialNode:GetCurrencyQuality()
    return checkInt(table.keys(self._prices)[1])
end

---获取货币列表
function CommonExchangeMaterialNode:GetCurrencyList()
    return self._currencyList
end

---获取物品最大选中数量
function CommonExchangeMaterialNode:GetMaxSelectedNum()
    local key = table.keys(self._prices)[1]
    return checkInt(self._prices[key].current) * self._buyNum
end

---获取当前选中数量
function CommonExchangeMaterialNode:GetCurrentSelectedNum()
    local num = 0
    for _, v in pairs(self._selectedItems) do
        num = num + v
    end
    return num
end

---获取cell的scr
function CommonExchangeMaterialNode:GetCellScr(cell)
    return CfUtils.GetLuaScr(cell, "Game.UI.Common.CommonExchangeMaterialListCell")
end
--endregion private

return CommonExchangeMaterialNode